import{_ as e,o as r,c as a,a5 as d}from"./chunks/framework.R-FQ1xZ2.js";const g=JSON.parse('{"title":"项目拆解","description":"","frontmatter":{"title":"项目拆解"},"headers":[],"relativePath":"projects/index.md","filePath":"projects/index.md","lastUpdated":null}'),l={name:"projects/index.md"};function o(n,t,h,i,s,c){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="项目拆解" tabindex="-1">项目拆解 <a class="header-anchor" href="#项目拆解" aria-label="Permalink to &quot;项目拆解&quot;">​</a></h1><blockquote><p>这一节不是「项目介绍」，是<strong>答辩稿</strong>。每一页都能单独抽出来回答面试官的一个追问。</p></blockquote><h2 id="两个项目-解决的是两件不同的事" tabindex="-1">两个项目，解决的是两件不同的事 <a class="header-anchor" href="#两个项目-解决的是两件不同的事" aria-label="Permalink to &quot;两个项目，解决的是两件不同的事&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th><a href="/learn/projects/yyhelp/">YYHelp v2 · 电商智能客服 Agent</a></th><th><a href="/learn/projects/rag/">科研文献 RAG 问答服务</a></th></tr></thead><tbody><tr><td><strong>一句话</strong></td><td>多轮对话<strong>能不能可靠地把事办完</strong></td><td>检索<strong>准不准</strong>、答案<strong>可不可核对</strong></td></tr><tr><td>控制流</td><td>LangGraph 状态图：分叉 / 汇合 / 循环</td><td>直线：问题 → 检索 → 生成 → 校验</td></tr><tr><td>状态</td><td>会话持久化 + 中断恢复</td><td>无状态</td></tr><tr><td>副作用</td><td>查订单、建工单（写操作，幂等键 + 人工确认）</td><td>只读</td></tr><tr><td>检索</td><td>Milvus 单库双路（dense + sparse）+ RRF + 精排</td><td>FAISS dense + 自建 BM25 + RRF + 精排</td></tr><tr><td>可观测</td><td>自研 JSONL + Langfuse v4 双后端，显式降级</td><td>自研 JSONL</td></tr><tr><td>评测</td><td>配对比较 + Holm 校正 + 三态退出码（可进 CI）</td><td>分层评测集 + 消融实验全表</td></tr><tr><td>数据闭环</td><td>数据飞轮（三入口 → 问题池 → 离线重放）</td><td>无</td></tr></tbody></table><p><strong>为什么这两个项目放在一起讲才有力</strong>：它们不是同一个东西做两遍。前作解决「检索准不准」，本项目解决「多轮对话能不能可靠地把事办完」。面试官问「你为什么又做一个 RAG」，答案就是这张表。</p><h2 id="⏱-时间不够时的阅读顺序" tabindex="-1">⏱ 时间不够时的阅读顺序 <a class="header-anchor" href="#⏱-时间不够时的阅读顺序" aria-label="Permalink to &quot;⏱ 时间不够时的阅读顺序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>顺序</th><th>页面</th><th>为什么先读它</th></tr></thead><tbody><tr><td>1</td><td><a href="/learn/projects/yyhelp/03-architecture.html">YYHelp · 总体架构</a></td><td>主图，一切追问从这里分叉</td></tr><tr><td>2</td><td><a href="/learn/projects/yyhelp/04-execution-loop.html">YYHelp · 核心执行循环</a></td><td>被要求「画一下」的概率最高</td></tr><tr><td>3</td><td><a href="/learn/projects/rag/04-retrieval.html">RAG · 检索层</a></td><td>混合检索 + RRF + 自检失效，最硬的加分项</td></tr><tr><td>4</td><td><a href="/learn/projects/rag/07-guardrails.html">RAG · 拒答与护栏</a></td><td>双层拒答，数字干净好讲</td></tr><tr><td>5</td><td><a href="/learn/projects/yyhelp/11-evaluation.html">YYHelp · 评测与回归门禁</a></td><td>唯一能反手把话题引到「我知道我实验设计的边界在哪」的地方</td></tr><tr><td>6</td><td><a href="/learn/projects/yyhelp/16-pitfalls.html">YYHelp · 工程踩坑实录</a></td><td>临场救场用；每个坑都能讲成加分项</td></tr></tbody></table><h2 id="三条贯穿两个项目的口径纪律" tabindex="-1">三条贯穿两个项目的口径纪律 <a class="header-anchor" href="#三条贯穿两个项目的口径纪律" aria-label="Permalink to &quot;三条贯穿两个项目的口径纪律&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">报数之前先想清楚这三条</p><ol><li><strong>不假装跑过。</strong> 未执行的验证就写「未执行验证」，并给一条可执行的验收命令。面试官追问「你怎么验的」时，答得上来比数字大更重要。</li><li><strong>报数必带口径。</strong> <code>recall@5</code> 要说清 macro 还是 micro、k 取几、是否含精排、分母怎么定义、ground truth 从哪来。同一个指标换个口径能差十几个点。</li><li><strong>配置类开关必须配「能失败的断言」。</strong> 只验「没报错」等于没验。中文分词器那个坑就是活例子——<strong>不报错、只返回空</strong>。</li></ol></div><h2 id="与面试准备的关系" tabindex="-1">与面试准备的关系 <a class="header-anchor" href="#与面试准备的关系" aria-label="Permalink to &quot;与面试准备的关系&quot;">​</a></h2><ul><li>完整数字与出处：<a href="/learn/interview/cheatsheet.html">🔥 面试随身数字卡</a></li><li>追问链预演：<a href="/learn/interview/project-grilling.html">项目深挖预演</a></li><li>通用高频题：<a href="/learn/interview/agent.html">Agent 与工具调用</a>、<a href="/learn/interview/rag.html">RAG</a>、<a href="/learn/interview/llm.html">大模型原理</a></li><li>原理图：<a href="/learn/diagrams/">架构图库</a> —— YYHelp 组 14 张、RAG 项目组 11 张</li></ul><h2 id="两个项目的共同技术底座" tabindex="-1">两个项目的共同技术底座 <a class="header-anchor" href="#两个项目的共同技术底座" aria-label="Permalink to &quot;两个项目的共同技术底座&quot;">​</a></h2><p><code>bge-m3</code> Embedding、<code>bge-reranker-v2-m3</code> 精排、RRF 融合、OpenAI 兼容协议调用 LLM、拒答阈值思路——这部分<strong>两个项目都用了</strong>，面试时只需要讲一次，然后说明「第二次我为什么要换成 Milvus / 换成 LangGraph」。</p>',13)])])}const m=e(l,[["render",o]]);export{g as __pageData,m as default};
